std::complex<double> ampqqbgll(int p1, int p2, int p3, int p4, int p5, 
                                 std::complex<double> al, std::complex<double> be, 
                                 std::complex<double> ga, std::complex<double> de, 
                                 FArray2D<std::complex<double>>& za, 
                                 FArray2D<std::complex<double>>& zb) {
    std::complex<double> ampqqbgll;

    ampqqbgll =
        al * za(p1, p2) * zb(p1, p5) * za(p4, p2) / (za(p1, p3) * za(p3, p2)) +
        be * zb(p3, p5) * za(p4, p2) / za(p1, p3) +
        ga * zb(p3, p1) * zb(p3, p5) * za(p4, p1) / (za(p1, p3) * zb(p2, p3)) +
        de * zb(p3, p1) / (za(p1, p3) * zb(p2, p1)) *
        (zb(p1, p5) * za(p4, p1) + zb(p2, p5) * za(p4, p2) + zb(p3, p5) * za(p4, p3));

    return ampqqbgll;
}

